steps = [
    step("Boot 给 HTTP 客户端选了什么底层。类路径上只有 spring-boot-starter-restclient(没有 Apache、Jetty),ClientHttpRequestFactoryBuilder.detect() 建出 JdkClientHttpRequestFactory,RestTemplateBuilder.build() 用的也是 JdkClientHttpRequestFactory;而直接 new RestTemplate() 是 SimpleClientHttpRequestFactory(基于 HttpURLConnection)。设 spring.http.clients.imperative.factory=simple 之后,RestTemplateBuilder 改成了 SimpleClientHttpsRequestFactory,RestClient 发出的请求头也变成 User-Agent: Java/21.0.12.1、Connection: keep-alive(原来是 Java-http-client/21.0.12.1)。同一个 RestClient,换个属性就换了整个底层客户端。", t=tl(S(1)), mark=lidx(S(1), 'new RestTemplate() 的工厂', 'imperative.factory=simple 时 RestClient'), done=lidx(S(1), 'detect() 建出', 'RestTemplateBuilder.build()', 'rc-boot'), b=bars([['Boot 构建的 RestClient / RestTemplate 底层', 1, 'JDK HttpClient'], ['new RestTemplate() 底层', 1, 'HttpURLConnection'], ['factory=simple 后 RestClient 的 User-Agent', 1, 'Java/21(不再是 Java-http-client)']], 1, done=[0], mark=[1, 2]), kv=KV([['有 Boot 配置时', '没有 Apache 就用 JDK HttpClient'], ['new RestTemplate()', 'HttpURLConnection(Simple 工厂)'], ['换底层', 'spring.http.clients.imperative.factory'], ['新属性前缀', 'spring.http.clients(有 s)']], ['换底层'])),
    step("请求头里能看出底层是谁。Boot 的 RestClient、RestClient.create()、RestTemplateBuilder 三者都是 JDK 客户端:User-Agent: Java-http-client/21.0.12.1,Connection: Upgrade, HTTP2-Settings,Upgrade: h2c,Accept-Encoding: gzip——明文 HTTP 上它会先尝试升级到 HTTP/2。new RestTemplate() 是 User-Agent: Java/21.0.12.1,Connection: keep-alive。RestClient 没有带 Accept 头,RestTemplate 带的是 text/plain, application/json, application/*+json, */*。", t=tl(S(2)), mark=lidx(S(2), 'rt-new'), done=lidx(S(2), 'rc-boot', 'rc-create', 'rt-boot'), b=bars([['JDK 客户端发 Upgrade: h2c 的个数', 3, '3(rc-boot、rc-create、rt-boot)'], ['HttpURLConnection 发 Upgrade 的个数', 0, '0(rt-new)']], 3, done=[0], mark=[1]), kv=KV([['JDK 客户端', 'Upgrade: h2c,Accept-Encoding: gzip'], ['HttpURLConnection', 'Connection: keep-alive'], ['Accept', 'RestClient 不带,RestTemplate 带一串']], ['JDK 客户端'])),
    step("连接复用。顺序发 20 次请求:Boot 的 RestClient.Builder、RestClient.create()、RestTemplateBuilder、new RestTemplate() 四种,服务端都只收到 1 个新连接——keep-alive 复用,不用自己配连接池。20 个线程并发(每个请求在服务端睡 300 ms):四种都是 20 个新连接,总用时 376、387、382、338 ms,接近单个请求的 300 ms。两种 JDK 客户端和 HttpURLConnection 在并发时都不限制连接个数。", t=tl(S(3)), mark=lidx(S(3), '并发 20 个线程'), done=lidx(S(3), '顺序 20 次'), b=bars([['顺序 20 次的新连接数', 1, '1'], ['并发 20 个线程的新连接数', 20, '20'], ['并发 20 个线程的总用时 ms(Boot RestClient)', 376, '376']], 376, done=[0], mark=[1, 2]), kv=KV([['顺序', '1 个连接复用到底'], ['并发', '每个线程一个新连接'], ['上限', '这三种客户端默认没有限制'], ['结论', '没有 Apache 时不需要调连接池']], ['并发'])),
    step("超时。服务端 3 秒才响应,不配置任何超时:RestClient 读到 slow-done,用了 3051 ms;Boot 构建的 RestTemplate 3011 ms;new RestTemplate() 3013 ms。三个客户端默认都没有读超时。用旧的属性名 spring.http.client.read-timeout=500ms:没有任何效果,还是 3046、3010、3011 ms,而且没有任何报错。换成 spring.http.clients.read-timeout=500ms:RestClient 和 Boot 构建的 RestTemplate 分别在 522 ms 和 514 ms 抛 ResourceAccessException ← HttpTimeoutException;new RestTemplate() 不受影响,仍是 3012 ms——Boot 的属性只对 Boot 构建的客户端生效。", t=tl(S(4)), mark=lidx(S(4), '旧的属性名', '不配置任何超时'), done=lidx(S(4), 'spring.http.clients.read-timeout=500ms', 'HttpTimeoutException'), b=bars([['无超时配置,RestClient 用时 ms', 3051, '3051(等到底)'], ['旧属性名 read-timeout=500ms 用时 ms', 3046, '3046(没生效)'], ['新属性名 read-timeout=500ms 用时 ms', 522, '522(超时)'], ['new RestTemplate() 在新属性下用时 ms', 3012, '3012(不受影响)']], 3051, mark=[0, 1, 3], done=[2]), kv=KV([['默认', '没有读超时'], ['旧属性名', '静默无效'], ['新属性名', 'spring.http.clients.read-timeout'], ['异常', 'ResourceAccessException ← HttpTimeoutException']], ['旧属性名'])),
    step("连接超时。连一个不可达的地址 10.255.255.1:81。设 spring.http.clients.connect-timeout=300ms:331 ms 后抛 ResourceAccessException ← HttpConnectTimeoutException ← ConnectException。不配置:等了 20 秒仍没有返回,测试程序被强行终止(rc=-9)。没有连接超时的客户端在对端不可达时会一直占着调用线程。", t=tl(S(5)), mark=lidx(S(5), '不配置连接超时', '20 秒内没有返回'), done=lidx(S(5), 'connect-timeout=300ms', 'HttpConnectTimeoutException'), b=bars([['配置 300ms 后实际用时 ms', 331, '331'], ['不配置时等待至少 ms', 20000, '≥20000(被强行终止)']], 20000, done=[0], mark=[1]), kv=KV([['connect-timeout=300ms', '331 ms 后失败'], ['不配置', '至少挂 20 秒'], ['异常', 'HttpConnectTimeoutException'], ['必配项', '读超时和连接超时都要显式配置']], ['不配置'])),
    step("状态码。RestClient retrieve().body():200 返回 body-of-200;204 返回 null;404 抛 NotFound(带状态 404 和 body-of-404);500 抛 InternalServerError(带状态 500 和 body)。exchange() 不抛,自己拿状态和 body。onStatus 里抛自定义异常 → 抛出自己的 IllegalStateException;onStatus 用空处理器吞掉 500 → toBodilessEntity 得到状态 500。RestTemplate 对 404 同样抛 NotFound。", t=tl(S(6)), mark=lidx(S(6), '/s/404 → 抛', '/s/500 → 抛'), done=lidx(S(6), '/s/200', '/s/204', 'exchange()', 'onStatus'), b=bars([['4xx / 5xx 默认抛异常的个数', 2, '2(404、500)'], ['204 返回 null 的个数', 1, '1'], ['exchange 抛异常的个数', 0, '0']], 2, mark=[0], done=[1, 2]), kv=KV([['retrieve()', '4xx/5xx 抛 NotFound、InternalServerError 这类异常,带状态和 body'], ['204', 'body 为 null'], ['exchange()', '不抛,自己判断'], ['onStatus', '自定义抛什么或吞掉']], ['retrieve()'])),
    step("HTTP Interface。声明一个接口,用 @GetExchange 标方法,@RequestParam、@RequestHeader、@PathVariable 绑定参数,通过 HttpServiceProxyFactory 加 RestClientAdapter 生成代理。api.echo(x=\"a b\", h=\"H1\") 服务端收到 x=a b、X-Test=H1;api.status(200) 返回 body-of-200;返回类型写成 ResponseEntity<Void> 调 404 仍然抛 NotFound(不是返回 404 的 ResponseEntity);api.status(500) 抛 InternalServerError,状态 500。异常行为和 RestClient 一样,因为底层就是 RestClient。", t=tl(S(7)), mark=lidx(S(7), 'statusEntity(404) 抛', 'status(500) 抛'), done=lidx(S(7), 'api.echo', 'api.status(200)'), b=bars([['api.echo 服务端收到的参数个数', 2, '2(x 和 X-Test)'], ['ResponseEntity 返回 404 仍然抛的个数', 1, '1'], ['500 抛异常的个数', 1, '1']], 2, done=[0], mark=[1, 2]), kv=KV([['声明式接口', '@GetExchange + 参数注解'], ['代理', 'HttpServiceProxyFactory + RestClientAdapter'], ['404 / 500', '和 RestClient 一样抛异常'], ['ResponseEntity 返回值', '不会让 404 变成正常返回']], ['ResponseEntity 返回值'])),
    step("重定向。默认情况下,Boot 构建的 RestClient、RestTemplate 和 new RestTemplate() 请求 /redirect(302 到 /fast)都跟随到最终的 ok。设 spring.http.clients.redirects=dont-follow:RestClient 返回状态 302、body 为 null;Boot 构建的 RestTemplate.getForObject 返回 null,没有任何异常;new RestTemplate() 不受影响,仍然跟随得到 ok。", t=tl(S(8)), mark=lidx(S(8), 'dont-follow', '状态 302', "→ 'null'"), done=lidx(S(8), '默认:', "body='ok'"), b=bars([['默认 RestClient 状态', 200, '200(跟随)'], ['dont-follow 后 RestClient 状态', 302, '302'], ['dont-follow 后 new RestTemplate() 状态', 200, '200(不受影响)']], 302, done=[0, 2], mark=[1]), kv=KV([['默认', '三种客户端都跟随重定向'], ['dont-follow', '只对 Boot 构建的客户端生效'], ['RestTemplate.getForObject', '302 不抛异常,返回 null'], ['注意', '不跟随时要自己处理 Location']], ['RestTemplate.getForObject'])),
    step("换成 Apache HttpClient 5(类路径上加 httpclient5)。detect() 变成 HttpComponentsClientHttpRequestFactory。30 个并发请求(每个在服务端睡 300 ms):Boot 默认的 RestClient 只用了 5 个连接,总用时 1886 ms(分批排队);自己配连接池(总 100、每个路由 50)后用了 30 个连接,361 ms。连接池只有 2 个连接并且等连接最多 200 ms 时,6 个并发请求:成功 2 个,4 个失败,异常是 ResourceAccessException ← ConnectionRequestTimeoutException,总用时 642 ms。有连接池的客户端,连接上限和「等连接的超时」是两个要配的参数。", t=tl(S(9)), mark=lidx(S(9), '连接池只有 2 个连接', 'Boot 的 RestClient.Builder(默认)'), done=lidx(S(9), '自己配的连接池', 'detect() 建出'), b=bars([['Apache 默认:30 并发用的连接数', 5, '5(1886 ms)'], ['自配连接池:30 并发用的连接数', 30, '30(361 ms)'], ['连接池 2 个、6 并发:失败的请求数', 4, '4']], 30, mark=[0, 2], done=[1]), kv=KV([['Apache 默认', '每个路由 5 个连接,并发请求排队'], ['自配连接池', 'maxConnPerRoute 等可调'], ['等连接超时', 'ConnectionRequestTimeoutException'], ['建议', '用 Apache 时把池大小和等待超时显式配好']], ['建议'])),
]
